/**
 * Before-insert handler for Case.
 *
 * If the case's Account has Rating = 'Hot', override Priority to 'High'.
 * All other cases keep whatever Priority the caller supplied.
 *
 * Bulk-safe: Account.Rating is fetched with a single SOQL per trigger
 * invocation, regardless of batch size (Email-to-Case = 1, ERP = up to 200).
 */
public with sharing class CasePriorityHandler {

    public static void handleBeforeInsert(List<Case> newCases) {

        // 1. Collect the Account Ids we need to look up (skip nulls).
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // 2. One query for the whole batch instead of one-per-row.
        //    Governor limit is 100 SOQL per transaction; 200 rows inside
        //    a loop would exceed it, so we stay outside the loop.
        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]
        );

        // 3. Walk the cases again and bump Priority where the account is Hot.
        for (Case c : newCases) {
            if (c.AccountId != null) {
                Account acc = accountMap.get(c.AccountId);
                if (acc != null && acc.Rating == 'Hot') {
                    c.Priority = 'High';
                }
            }
        }
    }
}
```

### Why this shape

| Concern | How it's addressed |
|---|---|
| **Bulk / governor limits** | One SOQL per invocation; a 200-case ERP batch costs 1 query, not 200. |
| **Cases with no Account** | Guarded by `c.AccountId != null`; they fall through and keep their supplied Priority. |
| **Cases with an Account that isn't Hot** | `acc.Rating == 'Hot'` is the only path that mutates `Priority`; everything else is untouched. |
| **`with sharing`** | Prevents the handler from silently bypassing org-sharing rules if a future refactor introduces a `Database.withoutSharing` wrapper or a `@AuraEnabled` entry point. |
| **Readability for admins** | Three clearly labelled steps (collect → query → assign), no helper classes, no interfaces, no trigger-framework dependency. |

