     */
    public static void onBeforeInsert(List<OpportunityLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        for (OpportunityLineItem line : newLines) {
            // Only fill in when the field was left empty; 0 is a valid rep choice.
